namespace {
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
template<class T,class A>void shortBudgets(T&task,const kstation::FlashCredits&credits,unsigned&calls,uint64_t&checks,A&&advance){auto cost=task.nextClocks(credits);std::array<uint8_t,sizeof(T)>snapshot;std::memcpy(snapshot.data(),&task,sizeof(T));auto before=calls;for(unsigned budget=0;budget<cost;++budget){check(!advance(budget)&&calls==before&&!std::memcmp(snapshot.data(),&task,sizeof(T)),"Short budget mutated task/IO");++checks;}}
class Original final:public H8SEmulator{public:int readHistory()const{return lastread;}int writeHistory()const{return lastwrite;}int irqDepth()const{return indent;}void histories(int r,int w){lastread=r;lastwrite=w;}void irqDepth(int d){indent=d;}};
using C=kstation::Stage1Cpu;
struct Event{uint64_t clocks;unsigned pc,at;std::array<int32_t,8>regs;uint8_t flags,exr,value;bool write;};
template<class Cpu>class Bus final:public H8SDevice{public:Cpu&c;unsigned count=0,command=0,remaining=0,pageWrites=0,lcdReads=0,lcdBusy=0,lastReads=0,stallReads=0;bool dropLast=false;unsigned dropIndex=~0u;uint32_t page=0,tick=0;std::array<Event,8>events{};explicit Bus(Cpu&p):c(p){}void record(unsigned at,uint8_t v,bool w){check(count<events.size(),"IO overflow");auto&e=events[count++];e={c.cycles,unsigned(c.getPC()),at,{},c.ccr,c.exr,v,w};for(unsigned j=0;j<8;++j)e.regs[j]=c.regs[j].er;}uint8_t read(unsigned at)override{uint8_t v=c.memory[at];if(at==0x600004)v=uint8_t(6|(c.memory[0x600000]&8?16:0));if(at>=0xfffd20&&at<=0xfffd23){if(at==0xfffd20)tick=uint32_t(c.cycles/1000);v=uint8_t(tick>>((0xfffd23-at)*8));}if(at==0xffffc7)v=lcdReads++<lcdBusy?0x80:0;if(pageWrites==256&&at==page+255&&lastReads++<stallReads)v^=1;record(at,v,false);return v;}
 void write(unsigned at,uint8_t v)override{record(at,v,true);if(at>=0x200000&&at<0x240000){auto offset=at-0x200000;if(command==3){if(!pageWrites)page=at;if((!dropLast||remaining!=1)&&pageWrites!=dropIndex)c.memory[at]=v;++pageWrites;if(!--remaining)command=0;return;}if(command==0&&offset==0x5555&&v==0xaa)command=1;else if(command==1&&offset==0x2aaa&&v==0x55)command=2;else if(command==2&&offset==0x5555&&v==0xa0){command=3;remaining=256;}else command=0;return;}c.memory[at]=v;}
};
struct Fixture {std::unique_ptr<Original>a=std::make_unique<Original>();std::unique_ptr<C>b=std::make_unique<C>();Bus<Original>x{*a};Bus<C>y{*b};kstation::NativeStartupControl native;uint64_t openChildren=0,originalChildren=0;uint64_t handlers=0,steps=0,io=0,programs=0,irqSteps=0,mutations=0;bool nested=false,mutate=false,injected=false;void byte(unsigned at,unsigned v){a->memory[at&0xffffff]=b->memory[at&0xffffff]=uint8_t(v);}void word(unsigned at,unsigned v){byte(at,v>>8);byte(at+1,v);}void wide(unsigned at,unsigned v){word(at,v>>16);word(at+2,v);}
 explicit Fixture(const std::vector<uint8_t>&rom){a->loadmem(rom.data(),rom.size(),0);b->loadmem(rom.data(),rom.size(),0);for(auto r:{std::pair{0x200000,0x40000},std::pair{0xfffd00,0x300},std::pair{0xbb00,0x200},std::pair{0xce00,0x400},std::pair{0xcd00,0x100},std::pair{0xc580,0x30},std::pair{0x600000,16},std::pair{0x3fff80,0x100}}){a->memmap(&x,r.first,r.second);b->memmap(&y,r.first,r.second);}}
 void prepare(unsigned entry,unsigned flags,unsigned target=0x21fe00,unsigned sp=0xffff00){native.reset();for(unsigned j=0;j<8;++j)a->regs[j].er=b->regs[j].er=int32_t(0x9a6c0011+j*0x122334);a->pc=a->makepc(entry);b->pc=b->makepc(entry);a->setSP(sp);b->setSP(sp);wide(sp,0x3ae8);a->reg32(5)=b->reg32(5)=0xce1e;a->reg32(6)=b->reg32(6)=target;a->cycles=b->cycles=flags==255?~uint64_t(0)-5:100000;a->ccr=b->ccr=uint8_t(flags);a->exr=b->exr=0x5a;a->pending_irqs=b->pending_irqs=0;a->histories(0x200001,0xfffe6f);b->histories(0x200001,0xfffe6f);a->irqDepth(3);b->irqDepth(3);x.command=y.command=x.remaining=y.remaining=x.pageWrites=y.pageWrites=x.lcdReads=y.lcdReads=x.lcdBusy=y.lcdBusy=x.lastReads=y.lastReads=x.stallReads=y.stallReads=0;x.dropLast=y.dropLast=false;x.dropIndex=y.dropIndex=~0u;nested=mutate=injected=false;word(0xfffe32,0xfffe);for(unsigned j=0;j<256;++j){byte(0xce1e + j,j*73+19);byte(0x21fe00+j,j*73+19);byte(0x21ff00+j,j*13+7);}for(unsigned j=0;j<23;++j)byte(0xbb12+j,j*17+3);++handlers;}
 void equal(unsigned at){bool same=a->cycles==b->cycles&&a->getPC()==b->getPC()&&a->ccr==b->ccr&&a->exr==b->exr&&a->readHistory()==b->readHistory()&&a->writeHistory()==b->writeHistory()&&a->irqDepth()==b->irqDepth();for(unsigned j=0;j<8;++j)same&=a->regs[j].er==b->regs[j].er;if(!same){std::fprintf(stderr,"At%x PC%x/%x clocks%llu/%llu flags%x/%x R0%x/%x R1%x/%x R2%x/%x R5%x/%x R6%x/%x\n",at,a->getPC(),b->getPC(),a->cycles,b->cycles,a->ccr,b->ccr,a->reg32(0),b->reg32(0),a->reg32(1),b->reg32(1),a->reg32(2),b->reg32(2),a->reg32(5),b->reg32(5),a->reg32(6),b->reg32(6));throw std::runtime_error("Context differs");}check(x.count==y.count,"IO count differs");for(unsigned j=0;j<x.count;++j){auto&p=x.events[j];auto&q=y.events[j];if(!(p.clocks==q.clocks&&p.pc==q.pc&&p.at==q.at&&p.regs==q.regs&&p.flags==q.flags&&p.exr==q.exr&&p.value==q.value&&p.write==q.write)){std::fprintf(stderr,"IO At%x event%u at%x/%x value%x/%x flags%x/%x clocks%llu/%llu\n",at,j,p.at,q.at,p.value,q.value,p.flags,q.flags,p.clocks,q.clocks);throw std::runtime_error("IO context differs");}}io+=x.count;}
 void run(unsigned stop,unsigned marker=0){bool injectedMarker=false;for(unsigned j=0;j<2000000;++j){auto at=unsigned(a->getPC());if(at==stop){++openChildren;return;}if(at==0x1a6&&!injectedMarker){byte(0xfffe3d,marker);injectedMarker=true;}x.count=y.count=0;if(native.step(*b)){a->step();++steps;}else{check(native.requestedChild()!=0,"Unowned startup phase");a->step();b->step();++originalChildren;}equal(at);}throw std::runtime_error("Startup control graph stalled");}
};}
int main(int argc,char**argv){try{if(argc<2){std::puts("SKIP private K ROM required");return 77;}std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};check(rom.size()==49728,"ROM size");Fixture f(rom);
 for(unsigned entry:{0x142u,0x15cu,0x166u})for(unsigned flags:{0u,0x2fu,0x80u,0xffu})for(unsigned marker:{0u,0x55u,0xaau}){f.prepare(entry,flags);f.run(marker?0x382:0x2fe,marker);}
 for(unsigned entry:{0x240u,0x3a58u})for(unsigned flags=0;flags<256;++flags){f.prepare(entry,flags);f.run(entry==0x240?0x232e:0x5aa0);}
 f.prepare(0x3a58,0x80);for(unsigned j=0;j<48;++j)f.byte(0x21fc00+j,rom[0x110+j]);for(unsigned j=0;j<23;++j)f.byte(0x21ff00+j,rom[0xbb12+j]);for(unsigned j=0;j<128;++j)f.byte(0x226400+j,rom[0xba5c+j]);f.byte(0xd022,8);f.word(0xc400,0x8000);f.run(0x3ae4);
 uint64_t shorts=0,blocked=0;unsigned calls=0;kstation::FlashCredits cr;
 using P=kstation::StartupPrefixTask;for(unsigned marker:{0u,0x55u,0xaau}){P task;while(!task.complete()){if(task.awaiting()){check(!task.nextClocks(cr),"Prefix child gate");task.resume();++blocked;continue;}auto advance=[&](unsigned budget){return task.advanceBefore(budget,cr,[&]{++calls;return marker;},[&](auto){++calls;});};shortBudgets(task,cr,calls,shorts,advance);advance(task.nextClocks(cr));}check(task.romCopy()==(marker!=0),"Prefix marker choice");}
 using R=kstation::StartupRuntimeTask;{R task;while(!task.complete()){if(task.awaiting()){check(!task.nextClocks(cr),"Runtime child gate");task.resume();++blocked;continue;}auto advance=[&](unsigned budget){return task.advanceBefore(budget,cr);};shortBudgets(task,cr,calls,shorts,advance);advance(task.nextClocks(cr));}}
 using M=kstation::StartupMainTask;{M task;while(!task.complete()){if(task.awaiting()){check(!task.nextClocks(cr),"Main child gate");task.resume(0x9a);++blocked;continue;}auto advance=[&](unsigned budget){return task.advanceBefore(budget,cr,[&](M::Read field){++calls;return field==M::Read::Bank?4u:99u;},[&](M::Write field,unsigned value){++calls;check(value==(field==M::Write::Bank?4u:field==M::Write::Program?99u:0x9au),"Main publication");});};shortBudgets(task,cr,calls,shorts,advance);advance(task.nextClocks(cr));}}
 std::printf("{\"passed\":true,\"prefix_cases\":%llu,\"native_control_phases\":%llu,\"ordered_context_io\":%llu,\"original_child_steps\":%llu,\"full_boot_closed\":false,\"pure_short_budgets\":%llu,\"child_gates\":%llu}\n",f.openChildren,f.steps,f.io,f.originalChildren,shorts,blocked);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL:%s\n",e.what());return 1;}}
